  });
  it.todo("a single sword (no modifiers, long-standing customer) → base premium 100 G");
  it.todo("a single amulet → base premium 60 G");
  it.todo("a single staff → base premium 80 G");
  it.todo("a single potion → base premium 40 G");
  it.todo("a single rune → base premium 25 G");
  it.todo("a single moonstone → base premium 25 G");
});

describe("MHPCO Claim Office — quote: building block of 3 alike components", () => {
  it.todo("2 runes → 50 G base premium");
  it.todo("3 runes → 60 G base premium (block applies)");
  it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
  it.todo("7 runes → 175 G base premium");
  it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
  it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
});

describe("MHPCO Claim Office — quote: item-specific modifiers", () => {
  it.todo("cursed sword adds 50 % risk surcharge → 150 G before fee");
  it.todo("sword with enchantment 5 → high-enchantment surcharge applies (30 %) → 130 G before fee");
  it.todo("sword with enchantment 4 → no high-enchantment surcharge → 100 G before fee");
  it.todo("cursed sword with enchantment 5 → both surcharges apply → 180 G before fee");
  it.todo("cursed sword (100 G) + plain amulet (60 G) → policy base 160 G + 50 G curse = 210 G before further modifiers and fee");
});

describe("MHPCO Claim Office — quote: policy-wide modifiers", () => {
  it.todo("customer with exactly 2 years with MHPCO → 20 % loyalty discount applies");
  it.todo("customer with 1 year with MHPCO → no loyalty discount");
  it.todo("first insurance carries a 10 % initial assessment surcharge on every quote's items");
  it.todo("second contract in a scenario receives a 15 % follow-up discount");
  it.todo("a 5 G processing fee is added to every premium at the very end");
});

describe("MHPCO Claim Office — quote: rounding in the MHPCO's favor", () => {
  it.todo("a premium calculation that yields 197.5 G → final premium 198 G (rounded up)");
  it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
});

describe("MHPCO Claim Office — quote: integration examples", () => {
  it.todo("newcomer (0 years, no previous contract) with a cursed sword (steel, enchantment 3) → premium 165 G");
  it.todo("long-standing customer (3 years), second quote, cursed sword (steel, enchantment 7) → premium 160 G");
});

describe("MHPCO Claim Office — quote: errors", () => {
  it.todo("quote includes an item with an unknown type (e.g. broomstick) → error");
});

describe("MHPCO Claim Office — claim: standard reimbursement", () => {
  it.todo("regular sword (steel, enchantment 3), damage 500 G → payout 400 G");
  it.todo("damage to a rune (no enchantment, no material), damage 200 G → payout 100 G");
  it.todo("deductible applies once per damaged item: sword 500 G + amulet 300 G → payout 600 G");
});

describe("MHPCO Claim Office — claim: special clauses", () => {
  it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % first, then deductible)");
  it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full reimbursement, then deductible)");
  it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins, then deductible)");
  it.todo("dragon-material sword with exactly enchantment 8, damage 1000 G → payout 400 G");
});

describe("MHPCO Claim Office — claim: cap", () => {
  it.todo("policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
  it.todo("cursed sword (premium with modifiers 165 G) → cap 2000 G (premium modifiers do not raise the cap)");
  it.todo("policy covering a sword and 3 runes (a block) → insurance sum 1750 G, cap 3500 G (block affects premium only)");
  it.todo("sword insured (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
  it.todo("sword insured (cap 2000 G), second successive claim of 1500 G → payout 600 G, remainingCap 0 G");
});

describe("MHPCO Claim Office — claim: multiple items of the same type", () => {
