describe("MHPCO Claim Office — claim: errors", () => {
  it.todo("damage entry whose item is not part of the policy (amulet damaged, only sword insured) → error");
  it.todo("damage entry with an unknown item type → error");
  it.todo("damage entry with amount -200 → error");
});

describe("MHPCO Claim Office — CLI", () => {
  it.todo("reads a scenario from stdin and writes {results: [...]} to stdout in step order");
  it.todo("schema example: quote amulet then claim 200 G → results [{premium}, {payout, remainingCap}]");
  it.todo("on an invalid scenario exits with a non-zero status code, writes an error to stderr and no results to stdout");
});

