const FIRST_INSURANCE_SURCHARGE = 0.1;

const BASE_PREMIUMS: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
  rune: 25,
  moonstone: 25,
};

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

const isBlockOfAlikeComponents = (items: Item[]): boolean =>
  items.length === BLOCK_SIZE &&
  items.every((item) => item.type === items[0].type);

const sumOfItemBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const policyBasePremium = (items: Item[]): number =>
  isBlockOfAlikeComponents(items)
    ? BLOCK_BASE_PREMIUM
    : sumOfItemBasePremiums(items);

// Deliberately `amount + amount * rate`, not `amount * (1 + rate)`:
// `1 + 0.1` is inexact in binary floating point, so the latter yields
// 110.00000000000001 for 100 G. Since premiums round UP (in MHPCO's favor),
// that epsilon would overcharge by a whole Gold piece.
const withFirstInsuranceSurcharge = (amount: number): number =>
  amount + amount * FIRST_INSURANCE_SURCHARGE;

const roundInMHPCOsFavor = (premium: number): number => Math.ceil(premium);

const quotePremium = (items: Item[]): number =>
  roundInMHPCOsFavor(
    withFirstInsuranceSurcharge(policyBasePremium(items)) + PROCESSING_FEE,
  );

