old='''const isBlockOfAlikeComponents = (items: Item[]): boolean =>
  items.length === BLOCK_SIZE &&
  items.every((item) => item.type === items[0].type);

const sumOfItemBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const policyBasePremium = (items: Item[]): number =>
  isBlockOfAlikeComponents(items)
    ? BLOCK_BASE_PREMIUM
    : sumOfItemBasePremiums(items);'''
new='''const groupByType = (items: Item[]): Map<string, Item[]> => {
  const groups = new Map<string, Item[]>();
  for (const item of items) {
    groups.set(item.type, [...(groups.get(item.type) ?? []), item]);
  }
  return groups;
};

const sumOfItemBasePremiums = (items: Item[]): number =>
  items.reduce((sum, item) => sum + BASE_PREMIUMS[item.type], 0);

const groupBasePremium = (alikeItems: Item[]): number =>
  alikeItems.length === BLOCK_SIZE
    ? BLOCK_BASE_PREMIUM
    : sumOfItemBasePremiums(alikeItems);

const policyBasePremium = (items: Item[]): number =>
  [...groupByType(items).values()].reduce(
    (sum, alikeItems) => sum + groupBasePremium(alikeItems),
    0,
  );'''
assert old in s
s=s.replace(old,new)
open(p,'w').write(s)
