  items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);

const damagePayout = (damage: Damage): number => damage.amount - DEDUCTIBLE;

const claimResult = (incident: Incident, insuredItems: Item[]): StepResult => {
  const payout = incident.damages.reduce(
    (total, damage) => total + damagePayout(damage),
    0,
  );
  const cap = insuranceSum(insuredItems) * CAP_MULTIPLE;
  return { payout, remainingCap: cap - payout };
};

