  step: Step,
  customer: Customer,
  previousContracts: number,
  insuredItemsOf: (policyIndex: number) => Item[],
): StepResult => {
  if (step.op === "quote") {
    return { premium: quotePremium(step.items, customer, previousContracts) };
  }
  return claimResult(step.incident, insuredItemsOf(step.policy));
};'''
